import{z as i,x as l,o as e,c as d,q as n,j as s,D as E,d as t,s as o,S as r,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"计数到无穷","description":"","frontmatter":{"title":"计数到无穷","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/count-to-infinity.md","filePath":"cs/count-to-infinity.md","lastUpdated":1791063341000}'),p={name:"cs/count-to-infinity.md"};function c(m,a,u,D,h,f){const A=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="计数到无穷" tabindex="-1">计数到无穷 <a class="header-anchor" href="#计数到无穷" aria-label="Permalink to &quot;计数到无穷&quot;">​</a></h1><div class="epigraph"><p>链路断了之后，邻居仍互相引用对方的旧距离，度量一步步加到协议的无穷大；坏消息比好消息慢。</p><footer>—— 据 Kurose and Ross 对距离向量缺陷；RFC 2453 对 RIP 无穷与毒性逆转的整理</footer></div><p><a href="/cs/distance-vector">上一课</a>把 Bellman-Ford 松弛放到路由器上：交换「到各前缀多远」。本课不重写更新公式。缺口是那一课已经点名、尚未钉死的失败模式：<strong>计数到无穷</strong>。好消息（更短）传得快，坏消息（不可达）在环上被当成「邻居还到得了」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>A 经 B 到网 X，代价 1。A–X 直连断开后，A 若立刻改从 B 走，而 B 的表仍写「经 A 代价 1」，双方交替加一，直到度量封顶才认不可达。缺口不是换一张图算法，而是距离向量<strong>只交换摘要、不交换路径</strong>时，无法区分「邻居的距离是否依赖我」。</p><p><span class="marginnote">无穷在 RIP 里常取 16。毒性逆转：从某口学来的路由，从该口通告为无穷。水平分割：不把从某口学来的路由再从该口送出。它们缩短计数，不消灭所有环。</span></p><p><span class="marginnote">直觉类比：两个人隔着墙互相指路。A 说「去 X 我这边断了，你那边能到吗」，B 查表答「经你可以到」——可 B 表里那条路恰恰要穿过 A。两人互相引用对方还没更新的旧话，谁也不肯先承认到不了，于是一起往上数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检测与缓解：水平分割、毒性逆转、触发更新、度量上限。破环的彻底办法是通告路径或拓扑（下一课链路状态），而不是再加快松弛频率。本课用两节点对偶把机制说清，不把 RIP 报文逐字段背完。</p>',9)),(e(),s(r,null,{default:E(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOWN%5B%22%E7%9B%B4%E8%BF%9E%E6%96%AD%E5%BC%80%22%5D%20--%3E%20REF%5B%22%E4%BB%8D%E5%BC%95%E7%94%A8%E9%82%BB%E5%B1%85%E7%9A%84%E6%97%A7%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20REF%20--%3E%20INC%5B%22%E5%BA%A6%E9%87%8F%E9%80%90%E6%AD%A5%E5%8A%A0%E4%B8%80%22%5D%0A%20%20INC%20--%3E%20INF%5B%22%E5%88%B0%E8%BE%BE%E7%BA%A6%E5%AE%9A%E6%97%A0%E7%A9%B7%E6%89%8D%E5%81%9C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"距离向量的数据是标量。标量相加在图上正确，当信息过时且形成依赖环时，加法变成「一起数到顶」。控制平面收敛时间可以远大于数据平面上那条链路已经静默的时间。端到端应用只看见丢包与绕路延迟，看不见计数过程。",-1)),(e(),s(r,null,{default:E(()=>[o(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20BRK%5B%22A%20%E5%88%B0%20X%20%E7%9A%84%E7%9B%B4%E8%BF%9E%E6%96%AD%E5%BC%80%22%5D%20--%3E%20A1%5B%22A%20%E6%9F%A5%E8%A1%A8%20%E7%BB%8F%20B%20%E4%BB%A3%E4%BB%B7%E8%AE%B0%202%22%5D%0A%20%20A1%20--%3E%20B1%5B%22B%20%E6%9F%A5%E8%A1%A8%20%E7%BB%8F%20A%20%E4%BB%A3%E4%BB%B7%E8%AE%B0%203%22%5D%0A%20%20B1%20--%3E%20A2%5B%22A%20%E5%86%8D%E6%9F%A5%E8%A1%A8%20%E7%BB%8F%20B%20%E4%BB%A3%E4%BB%B7%E8%AE%B0%204%22%5D%0A%20%20A2%20--%3E%20ELL%5B%22%E6%AF%8F%E8%BD%AE%E4%BA%92%E7%9B%B8%E5%8A%A0%E4%B8%80%20%E6%8C%81%E7%BB%AD%E6%95%B0%E8%BD%AE%22%5D%0A%20%20ELL%20--%3E%20CAP%5B%22%E5%88%B0%2016%20%E7%BA%A6%E5%AE%9A%E6%97%A0%E7%A9%B7%E6%89%8D%E8%AE%A4%E4%B8%8D%E5%8F%AF%E8%BE%BE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：RIP 更新周期 30 秒、无穷取 16。断链后每轮 A、B 互相加一：2、3、4……要数十来轮才到 16 认输，全网可能白等好几分钟，期间包被来回转送——这就是「坏消息比好消息慢」的具体账。</span></p><p><span class="marginnote">常见误区：以为毒性逆转治好了计数到无穷。它只对付两节点的小环，三个以上节点构成的环仍会互相计数。彻底解法是换信息——把路径本身通告出去（路径向量或链路状态），而不是只报一个数字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BGP 的路径向量提前当解药写完——BGP 带 AS 路径，是后课政策课的对象。也不把振荡的全部计时器组合写成配置指南。链路状态如何避免「只信邻居一句距离」，下一课。</p><p>后课默认：摘要距离会在断链后暂时撒谎。通告邻接图并各自计算，下一课链路状态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>坏消息在距离向量里会沿依赖环加到无穷。</li><li>水平分割与毒性逆转是缓解，不是证明。</li><li>链路状态换一种信息，下一课。</li><li>出处：Kurose and Ross；RFC 2453。</li></ul>',7))])}const P=i(p,[["render",c]]);export{F as __pageData,P as default};
